              calendar.dateComponents([.year, .month, .day], from: date) ==
                DateComponents(year: year, month: month, day: day) else { return nil }
        return date
    }

    /// Exact crossing projected onto a rule's civil calendar, independent of the current device zone.
    static func instant(for name: String, year: Int) -> Date? {
        guard supportedYears.contains(year), let index = names.firstIndex(of: name),
              let row = instantsByYear?[year - supportedYears.lowerBound] else { return nil }
        return row[index]
    }

    private static let instantsByYear: [[Date]]? = {
        let rows = encodedUTC.split(separator: "\n", omittingEmptySubsequences: false)
        guard rows.count == supportedYears.count, let legacy = daysByYear else { return nil }
        var taipei = Calendar(identifier: .gregorian)
        taipei.timeZone = TimeZone(identifier: "Asia/Taipei")!
        var result: [[Date]] = []
        var previous: Date?
        for (yearIndex, row) in rows.enumerated() {
            let fields = row.split(separator: ":", omittingEmptySubsequences: false)
            let year = supportedYears.lowerBound + yearIndex
            guard fields.count == 2, fields[0] == String(year) else { return nil }
            let values = fields[1].split(separator: ",", omittingEmptySubsequences: false)
            guard values.count == names.count else { return nil }
            var instants: [Date] = []
            for (index, value) in values.enumerated() {
                guard let milliseconds = Int64(value) else { return nil }
                let instant = Date(timeIntervalSince1970: Double(milliseconds) / 1_000)
