                guard parts.year == year, parts.month == index / 2 + 1,
                      parts.day == legacy[yearIndex][index],
                      previous.map({ instant > $0 }) ?? true else { return nil }
                instants.append(instant)
                previous = instant
            }
            result.append(instants)
        }
        return result
